// and fd.rs records why. Values are stable across POSIX platforms.
// ---------------------------------------------------------------------------

pub(crate) const F_GETFD: c_int = 1;
pub(crate) const F_SETFD: c_int = 2;
pub(crate) const FD_CLOEXEC: c_int = 1;

